draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 20);
  ctx.lineTo(W / 2, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 50);
  ctx.lineTo(W / 2 - 20, H / 2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 50);
  ctx.lineTo(W / 2 + 20, H / 2 + 70);
  ctx.stroke();

  // add a thought bubble
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 40, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('?', W / 2, H / 2 - 40);

  // animate the thought bubble
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 40 + Math.sin(t) * 10, 30, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
